world node {
    use aap:caps/types@0.1.0.{tick, run-info};

    import wasi:clocks/wall-clock@0.2.0;
    import aap:caps/http-client@0.1.0;

    export run: func(tick: tick) -> run-info;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::wasi::clocks::wall_clock;

struct Node;

/// Converts days since 1970-01-01 into (year, month, day).
/// Howard Hinnant's civil_from_days algorithm.
fn civil_date(z: i64) -> (i64, u32, u32) {
    let z = z + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = (if mp < 10 { mp + 3 } else { mp - 9 }) as u32;
    let y = yoe + era * 400 + (if m <= 2 { 1 } else { 0 });
    (y, m, d)
}

/// Percent-encodes a string for use as a URL query value (RFC 3986 unreserved set kept).
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        // Read the clock first so `started` is the instant the run began.
        let now = wall_clock::now();
        let secs = now.seconds;

        let days = (secs / 86_400) as i64;
        let (y, m, d) = civil_date(days);
        let date = format!("{:04}-{:02}-{:02}", y, m, d);

        // Enrichment call. A transport failure comes back as a value; the
        // result is discarded so the output does not depend on it.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&tick.reason)
        );
        let _ = http_client::fetch(&url);

        RunInfo {
            date,
            started: secs,
        }
    }
}

export!(Node);
```

